+  // 30s 上限：失败快速返回，提交已落本地，后续 commit 或 /dpi-sync 会再推。
+  const pushOpts = { ...opts, timeoutMs: 30000 };
   const r = await pushWithRebaseRetry(repoPath, pushOpts);
   return r.pushed
     ? { committed: true, pushed: true }
     : { committed: true, pushed: false, error: r.error };
 }

