    expect(normalizeGatewayBaseUrl("https://sui-xiang.com/v1")).toBe("https://sui-xiang.com/v1");
    expect(normalizeGatewayBaseUrl("https://sui-xiang.com/v1/")).toBe("https://sui-xiang.com/v1");
    expect(normalizeGatewayBaseUrl("https://sui-xiang.com/api?k=1#frag")).toBe(
      "https://sui-xiang.com/api/v1",
